#include "RefModel.h"
extern "C" void ref_model_eval(unsigned long long rst_i,unsigned long long clk_i,unsigned long long stb_i,unsigned long long we_i,unsigned long long* ref_dat_o,unsigned long long dat_i,unsigned long long* ref_int_o,unsigned long long adr_i,unsigned long long* ref_MOSI,unsigned long long* ref_SCLK,unsigned long long MISO){static VerilatedContext context;static RefModel model(&context);model.rst_i=rst_i;model.clk_i=clk_i;model.stb_i=stb_i;model.we_i=we_i;model.dat_i=dat_i;model.adr_i=adr_i;model.MISO=MISO;model.eval();*ref_dat_o=model.ref_dat_o;*ref_int_o=model.ref_int_o;*ref_MOSI=model.ref_MOSI;*ref_SCLK=model.ref_SCLK;}
